IF NOT(superState) THEN
    F_ApertureStatus := ApertureStatus.unknown;
ELSIF isOpen AND (NOT(isClosed)) THEN
    F_ApertureStatus := ApertureStatus.open;
ELSIF isClosed AND (NOT(isOpen)) THEN
    F_ApertureStatus := ApertureStatus.closed;
ELSIF NOT(isOpen OR isClosed) THEN
    F_ApertureStatus := ApertureStatus.partiallyOpen;
ELSIF isOpen AND isClosed THEN
    F_ApertureStatus := ApertureStatus.undefined;
ELSE
    F_ApertureStatus := ApertureStatus.invalid_model;
END_IF;

IF NOT(superState) THEN
    F_BusyStatus := BusyStatus.unknown;
ELSIF NOT(isBusy) THEN
    F_BusyStatus := BusyStatus.idle;
ELSIF isBusy THEN
    F_BusyStatus := BusyStatus.busy;
ELSE
    F_BusyStatus := BusyStatus.invalid_model;
END_IF;

IF NOT(superState) THEN
    F_StartedStatus := StartedStatus.unknown;
ELSIF isStarted THEN
    F_StartedStatus := StartedStatus.started;
ELSIF NOT(isStarted) THEN
    F_StartedStatus := StartedStatus.notStarted;
ELSE
    F_StartedStatus := StartedStatus.invalid_model;
END_IF;

IF NOT(superState) THEN
    F_EnabledStatus := EnabledStatus.unknown;
ELSIF isEnabled THEN
    F_EnabledStatus := EnabledStatus.enabled;
ELSIF NOT(isEnabled) THEN
    F_EnabledStatus := EnabledStatus.disabled;
ELSE
    F_EnabledStatus := EnabledStatus.invalid_model;
END_IF;

IF NOT(superState) THEN
    F_PoweredStatus := PoweredStatus.unknown;
ELSIF isEnabled THEN
    F_PoweredStatus := PoweredStatus.enabled;
ELSIF NOT(isEnabled) THEN
    F_PoweredStatus := PoweredStatus.disabled;
ELSE
    F_PoweredStatus := PoweredStatus.invalid_model;
END_IF;

IF NOT(superState) THEN
    F_HealthStatus := HealthStatus.unknown;
ELSIF isGood AND (NOT(hasWarning)) THEN
    F_HealthStatus := HealthStatus.good;
ELSIF isGood AND hasWarning THEN
    F_HealthStatus := HealthStatus.warning;
ELSIF NOT(isGood) THEN
    F_HealthStatus := HealthStatus.bad;
ELSE
    F_HealthStatus := HealthStatus.invalid_model;
END_IF;

IF NOT(superState) THEN
    F_InitializationStatus := InitializationStatus.unknown;
ELSIF state = InitializationStates.SHUTDOWN THEN
    F_InitializationStatus := InitializationStatus.shutdown;
ELSIF state = InitializationStates.INITIALIZING THEN
    F_InitializationStatus := InitializationStatus.initializing;
ELSIF state = InitializationStates.INITIALIZING_FAILED THEN
    F_InitializationStatus := InitializationStatus.initializingFailed;
ELSIF state = InitializationStates.INITIALIZED THEN
    F_InitializationStatus := InitializationStatus.initialized;
ELSIF state = InitializationStates.LOCKED THEN
    F_InitializationStatus := InitializationStatus.locked;
ELSE
    F_InitializationStatus := InitializationStatus.invalid_model;
END_IF;

IF NOT(superState) THEN
    F_MotionStatus := MotionStatus.unknown;
ELSIF actVel > (ABS(tolerance)) THEN
    F_MotionStatus := MotionStatus.forward;
ELSIF actVel < (-(ABS(tolerance))) THEN
    F_MotionStatus := MotionStatus.backward;
ELSIF TRUE THEN
    F_MotionStatus := MotionStatus.standstill;
ELSE
    F_MotionStatus := MotionStatus.invalid_model;
END_IF;

IF NOT(superState) THEN
    F_HiHiLoLoAlarmStatus := HiHiLoLoAlarmStatus.unknown;
ELSIF NOT(config.enabled) THEN
    F_HiHiLoLoAlarmStatus := HiHiLoLoAlarmStatus.disabled;
ELSIF config.enabled AND (value >= config.hiHi) THEN
    F_HiHiLoLoAlarmStatus := HiHiLoLoAlarmStatus.hiHi;
ELSIF config.enabled AND ((value >= config.hi) AND (value < config.hiHi)) THEN
    F_HiHiLoLoAlarmStatus := HiHiLoLoAlarmStatus.hi;
ELSIF config.enabled AND ((value > config.lo) AND (value < config.hi)) THEN
    F_HiHiLoLoAlarmStatus := HiHiLoLoAlarmStatus.ok;
ELSIF config.enabled AND ((value <= config.lo) AND (value < config.loLo)) THEN
    F_HiHiLoLoAlarmStatus := HiHiLoLoAlarmStatus.lo;
ELSIF config.enabled AND (value <= config.loLo) THEN
    F_HiHiLoLoAlarmStatus := HiHiLoLoAlarmStatus.loLo;
ELSE
    F_HiHiLoLoAlarmStatus := HiHiLoLoAlarmStatus.invalid_model;
END_IF;

IF NOT(superState) THEN
    F_OpeningStatus := OpeningStatus.unknown;
ELSIF isOpening AND (NOT(isClosing)) THEN
    F_OpeningStatus := OpeningStatus.opening;
ELSIF isClosing AND (NOT(isOpening)) THEN
    F_OpeningStatus := OpeningStatus.closing;
ELSIF NOT(isClosing OR isOpening) THEN
    F_OpeningStatus := OpeningStatus.standstill;
ELSE
    F_OpeningStatus := OpeningStatus.invalid_model;
END_IF;

IF NOT(superState) THEN
    F_OperatorStatus := OperatorStatus.unknown;
ELSIF state = OperatorStates.NONE THEN
    F_OperatorStatus := OperatorStatus.none;
ELSIF state = OperatorStates.TECH THEN
    F_OperatorStatus := OperatorStatus.tech;
ELSIF state = OperatorStates.OBSERVER THEN
    F_OperatorStatus := OperatorStatus.observer;
ELSE
    F_OperatorStatus := OperatorStatus.invalid_model;
END_IF;

IF NOT(superState) THEN
    F_OperatingStatus := OperatingStatus.unknown;
ELSIF state = OperatingStates.AUTO THEN
    F_OperatingStatus := OperatingStatus.auto;
ELSIF state = OperatingStates.MANUAL THEN
    F_OperatingStatus := OperatingStatus.manual;
ELSE
    F_OperatingStatus := OperatingStatus.invalid_model;
END_IF;

IF NOT(superState) THEN
    F_OperatingModeStatus := OperatingModeStatus.unknown;
ELSIF state = OperatingModeStates.LOCAL THEN
    F_OperatingModeStatus := OperatingModeStatus.local;
ELSIF state = OperatingModeStates.REMOTE THEN
    F_OperatingModeStatus := OperatingModeStatus.remote;
ELSE
    F_OperatingModeStatus := OperatingModeStatus.invalid_model;
END_IF;

IF NOT(superState) THEN
    F_ActivityStatus := ActivityStatus.unknown;
ELSIF NOT(isRunning) THEN
    F_ActivityStatus := ActivityStatus.notRunning;
ELSIF isRunning THEN
    F_ActivityStatus := ActivityStatus.running;
ELSE
    F_ActivityStatus := ActivityStatus.invalid_model;
END_IF;

